class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.tree = [
      { id: 'General group settings', children: [
        { id: 'Protection mode' },
        { id: 'Protection settings' },
      ]},
      { id: 'Distance protection', children: [
        { id: 'DISR settings', children: [
          { id: 'DIS1' }, { id: 'DIS2' }, { id: 'DIS3' }, { id: 'DIS4' }, { id: 'DIS5' }, { id: 'ARDIS' },
        ]},
      ]},
      { id: 'Logical protection', children: [
        { id: 'LP' }, { id: 'BF' }, { id: 'OC4' },
      ]},
      { id: 'Auxiliary supply protect...', children: [
        { id: 'LASR settings', children: [
          { id: 'LAS', tags: ['4','4'] }, { id: 'ARLAS', tags: ['4','4'] },
        ]},
      ]},
      { id: 'Overcurrent protection', children: [
        { id: 'OCR settings', children: [
          { id: 'OC 1' }, { id: 'OC 2' }, { id: 'OC 3' }, { id: 'EF 1' }, { id: 'EF 2' }, { id: 'EF 3' }, { id: 'NSOC' }, { id: 'AR OC', tags: ['4','4'] },
        ]},
        { id: 'OL settings', children: [
          { id: 'OL 1' }, { id: 'OL 2' },
        ]},
      ]},
      { id: 'Hot line protection', children: [
        { id: 'HLOC' }, { id: 'HLEF' }, { id: 'HLNSOC' },
      ]},
      { id: 'Sensitive earth fault pr...', children: [
        { id: 'SEFR settings', children: [
          { id: 'SEF', tags: ['4','4'] }, { id: 'AR SEF', tags: ['4','4'] },
        ]},
        { id: 'NAPR settings', children: [
          { id: 'NAP' }, { id: 'AR NAP' },
        ]},
      ]},
      { id: 'Voltage protection', children: [
        { id: 'LSR settings', children: [
          { id: 'LS', tags: ['4','4'] }, { id: 'AR LS' },
        ]},
        { id: 'UVR settings', children: [
          { id: 'UV' },
        ]},
      ]},
    ];
    this.checklistIds = ['DIS1', 'DIS2', 'OC 1', 'EF 1', 'SEF', 'LS', 'UV', 'ARDIS'];
    this.tableRows = [
      { isSection: true, label: 'System info' },
      { label: 'Firmware v.', designation: '', units: '', v1: '(19) 79.01.1', v2: '', v3: '', v4: '' },
      { label: 'Functionality', designation: '', units: '', v1: 'RRE', v2: '', v3: '', v4: '' },
      { isSection: true, label: 'DIS1' },
      { label: 'Operating mode', designation: 'Mode', units: '', v1: 'Disable', v2: 'Disable', v3: 'Disable', v4: 'Disable' },
      { label: 'Type of impedance zone', designation: 'IZ_type', units: '', v1: 'P', v2: 'P', v3: 'P', v4: 'P' },
      { label: 'Resetting time', designation: 'Tres', units: 's', v1: '0,02', v2: '0,02', v3: '0,02', v4: '0,02' },
      { label: 'Direction operating mode', designation: 'DOM', units: '', v1: 'Forward', v2: 'Forward', v3: 'Forward', v4: 'Forward' },
      { label: 'Tripping time', designation: 'Tt', units: 's', v1: '0,00', v2: '0,00', v3: '0,00', v4: '0,00' },
      { label: 'Pickup mode', designation: 'PM', units: '', v1: 'Disable', v2: 'Disable', v3: 'Disable', v4: 'Disable' },
      { label: 'Pickup current', designation: 'Ip', units: 'A', v1: '100,00', v2: '100,00', v3: '100,00', v4: '100,00' },
      { label: 'Pickup voltage', designation: 'Up', units: 'p.u.', v1: '1,00', v2: '1,00', v3: '1,00', v4: '1,00' },
      { label: 'Line impedance', designation: 'ZIn', units: 'Ω', v1: '50,00', v2: '50,00', v3: '50,00', v4: '50,00' },
      { label: 'Phase resistance', designation: 'Rp', units: 'Ω', v1: '50,00', v2: '50,00', v3: '50,00', v4: '50,00' },
      { label: 'Coefficient of reverse security', designation: 'Crs', units: 'p.u.', v1: '0,10', v2: '0,10', v3: '0,10', v4: '0,10' },
      { label: 'Maximum impedance', designation: 'R', units: 'Ω', v1: '50,00', v2: '50,00', v3: '50,00', v4: '50,00' },
      { label: 'Harmonics limit', designation: 'HarmLimit', units: 'p.u.', v1: '1,00', v2: '1,00', v3: '1,00', v4: '1,00' },
    ];
    const expanded = {};
    const markAll = (nodes) => nodes.forEach(n => { if (n.children) { expanded[n.id] = true; markAll(n.children); } });
    markAll(this.tree);
    this.state = { expanded, checkedIds: { 'DIS1': true, 'SEF': true }, pinnedMode: 'checked', selectedId: 'DIS1' };
  }

  toggleExpand(id) { this.setState(s => ({ expanded: { ...s.expanded, [id]: !s.expanded[id] } })); }
  selectRow(id) { this.setState({ selectedId: id }); }
  toggleChecked(id) {
    this.setState(s => {
      const next = { ...s.checkedIds };
      if (next[id]) delete next[id]; else next[id] = true;
      return { checkedIds: next };
    });
  }

  flatten(nodes, level, out) {
    nodes.forEach(n => {
      const hasChildren = !!(n.children && n.children.length);
      out.push({
        id: n.id, label: n.id, indent: 10 + level * 16, hasChildren,
        toggleChar: this.state.expanded[n.id] ? '▾' : '▸',
        tags: n.tags || [],
        rowClass: 'ps-tree-row' + (hasChildren ? ' is-group' : '') + (this.state.selectedId === n.id ? ' is-selected' : ''),
        onClick: hasChildren ? (() => this.toggleExpand(n.id)) : (() => this.selectRow(n.id)),
      });
      if (hasChildren && this.state.expanded[n.id]) this.flatten(n.children, level + 1, out);
    });
  }

  renderVals() {
    const rows = [];
    this.flatten(this.tree, 0, rows);
    const checklistItems = this.checklistIds.map(id => ({
      id, label: id, checked: !!this.state.checkedIds[id],
      onToggle: () => this.toggleChecked(id),
    }));
    const pinnedRows = this.checklistIds.filter(id => this.state.checkedIds[id]).map(id => ({ id, label: id }));
    return {
      treeRows: rows,
      checklistItems,
      pinnedRows,
      showPinnedSection: this.state.pinnedMode === 'checked' && pinnedRows.length > 0,
      pinnedModeIsChecked: this.state.pinnedMode === 'checked',
      pinnedModeIsUnchecked: this.state.pinnedMode === 'unchecked',
      setModeChecked: () => this.setState({ pinnedMode: 'checked' }),
      setModeUnchecked: () => this.setState({ pinnedMode: 'unchecked' }),
      tableRows: this.tableRows.map(r => ({ isSection: !!r.isSection, label: r.label, designation: r.designation || '', units: r.units || '', v1: r.v1 || '', v2: r.v2 || '', v3: r.v3 || '', v4: r.v4 || '' })),
    };
  }
}

